export const platformSettings = pgTable("platform_settings", {
	id: varchar().default(sql`gen_random_uuid()`).primaryKey().notNull(),
	key: varchar({ length: 255 }).notNull(),
	value: jsonb().notNull(),
	category: varchar({ length: 100 }).default('general'),
	description: text(),
	isPublic: boolean("is_public").default(false),
	updatedBy: varchar("updated_by"),
	createdAt: timestamp("created_at", { withTimezone: true, mode: 'string' }).defaultNow(),
	updatedAt: timestamp("updated_at", { withTimezone: true, mode: 'string' }).defaultNow(),
}, (table) => [
	index("platform_settings_category_idx").using("btree", table.category.asc().nullsLast().op("text_ops")),
	index("platform_settings_key_idx").using("btree", table.key.asc().nullsLast().op("text_ops")),
	foreignKey({
			columns: [table.updatedBy],
			foreignColumns: [users.id],
			name: "platform_settings_updated_by_fkey"
		}),
	unique("platform_settings_key_key").on(table.key),
]);
